import {execSync} from 'node:child_process';
for (const options of [undefined,null,{}, {shell: null}, {shell:true}, {shell:false}, {shell:''}, {shell:'/bin/sh'}, {encoding:'utf8'}, 'bad', []]) {
 try { const r=execSync('printf actual', options); console.log(JSON.stringify({options,ok:true,type:typeof r,out:String(r)})); }
 catch(e) { console.log(JSON.stringify({options,ok:false,code:e.code,message:e.message})); }
}
